#include <stdio.h>
int main(void) {
    int w[] = {10, 20, 30}, v[] = {60, 100, 120};
    double cap = 50, val = 0;
    for (int i = 0; i < 3 && cap > 0; i++) {
        if (w[i] <= cap) { val += v[i]; cap -= w[i]; }
        else { val += (double)v[i] / w[i] * cap; cap = 0; }
    }
    printf("%.0f\n", val);
    return 0;
}

#include <stdio.h>
int main(void) {
    int s[] = {1, 3, 0, 5}, f[] = {4, 5, 6, 7};
    int count = 0, last = 0;
    for (int i = 0; i < 4; i++)
        if (s[i] >= last) { count++; last = f[i]; }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
int main(void) {
    int s[] = {2, 1, 5, 6, 3}, f[] = {4, 5, 7, 8, 9};
    int count = 0, last = 0;
    for (int i = 0; i < 5; i++)
        if (s[i] >= last) { count++; last = f[i]; }
    printf("%d\n", 5 - count);
    return 0;
}

#include <stdio.h>
int main(void) {
    int coins[] = {25, 10, 5, 1};
    int amount = 63, cnt = 0;
    for (int i = 0; i < 4; i++)
        while (amount >= coins[i]) { amount -= coins[i]; cnt++; }
    printf("%d\n", cnt);
    return 0;
}

#include <stdio.h>
int main(void) {
    int s[] = {1, 2, 4}, f[] = {3, 5, 6};
    int n = 3, picks = 0, last = -1000;
    for (int i = 0; i < n; i++)
        if (s[i] >= last) { picks++; last = f[i]; }
    printf("%d\n", picks);
    return 0;
}

#include <stdio.h>
int main(void) {
    int c[] = {1, 3, 4};
    int dp[7] = {0};
    for (int a = 1; a <= 6; a++) {
        dp[a] = 999;
        for (int i = 0; i < 3; i++)
            if (c[i] <= a && dp[a - c[i]] + 1 < dp[a]) dp[a] = dp[a - c[i]] + 1;
    }
    printf("%d\n", dp[6]);
    return 0;
}
